CREATE OR REPLACE FUNCTION private.credential_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
    if p_value is null or p_value = '' then return null; end if;
    if char_length(p_value) <> 10 or p_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or substring(p_value from 1 for 4)::integer = 0 then
        raise exception 'invalid credential date' using errcode = '22008';
    end if;
    return pg_catalog.make_date(substring(p_value from 1 for 4)::integer,
        substring(p_value from 6 for 2)::integer, substring(p_value from 9 for 2)::integer);
end;
$function$

CREATE OR REPLACE FUNCTION private.credential_details_projection(p_record credentials)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
    cycle public.credential_cycles;
begin
    select * into cycle from public.credential_cycles
    where practice_id = p_record.practice_id and credential_id = p_record.id and cycle_number = 1;
    if not found then raise exception 'missing credential cycle'; end if;
    return private.credential_projection(p_record) || pg_catalog.jsonb_build_object(
        'issuer', p_record.issuer, 'jurisdiction', p_record.jurisdiction,
        'current_cycle', pg_catalog.jsonb_build_object('id', cycle.id,
            'cycle_number', cycle.cycle_number, 'date_revision', cycle.date_revision,
            'end_date', pg_catalog.to_char(cycle.end_date, 'YYYY-MM-DD'),
            'action_deadline', pg_catalog.to_char(cycle.action_deadline, 'YYYY-MM-DD')));
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_administrator()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    target uuid;
begin
    if tg_table_name = 'practices' then
        target := new.id;
    elsif tg_op = 'DELETE' then
        target := old.practice_id;
    else
        target := new.practice_id;
    end if;
    perform 1 from public.practices where id = target for update;
    if found and not exists (select 1 from public.practice_memberships
                             where practice_id = target and state = 'active'
                               and role = 'administrator') then
        raise exception 'Practice requires an active administrator' using errcode = '23514';
    end if;
    if tg_table_name = 'practice_memberships' then
        if tg_op = 'UPDATE' then
            if old.practice_id <> new.practice_id then
                raise exception 'Membership practice is immutable' using errcode = '23514';
            end if;
        end if;
    end if;
    return null;
end;
$function$

