CREATE OR REPLACE FUNCTION private.list_practice_register_with_maintenance(p_practice_id uuid, p_include_archived boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform private.require_register_member(p_practice_id, false);
    if p_include_archived is null then return '{"status":"invalid"}'::jsonb; end if;
    return pg_catalog.jsonb_build_object(
